static UINT iloMediaLayoutMessage = 0;
bool IsTaskbarGeometryMessage(UINT msg) {
  switch (msg) {
    case WM_SIZE:
    case WM_WINDOWPOSCHANGED:
    case WM_SETTINGCHANGE:
    case WM_DISPLAYCHANGE:
    case WM_DPICHANGED:
      return true;
    default:
      return false;
  }
}
